package studio.solocamera;
import android.content.Context;import android.content.res.AssetManager;import android.graphics.Typeface;import java.io.File;import java.util.HashMap;
final class EditorFonts {private static AssetManager assets;private static final HashMap<String,Typeface> faces=new HashMap<>();static void init(Context context){assets=context.getApplicationContext().getAssets();EditorSocialIcons.init(context);EditorTitleSounds.init(context);}static synchronized Typeface face(String name,int style){Typeface base=faces.get(name);if(base==null){try{if(name.startsWith("font:"))base=Typeface.createFromAsset(assets,"fonts/"+name.substring(5)+".ttf");else if(name.startsWith("file:"))base=Typeface.createFromFile(new File(name.substring(5)));else base=Typeface.create(name,Typeface.NORMAL);}catch(Exception e){base=Typeface.DEFAULT;}faces.put(name,base);}return Typeface.create(base,style);}}
